     9|  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
    10|  <style>
    11|    /* === RESET & ROOT === */
    12|    *, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }
    13|    :root {
    14|      --bg-primary: #0f172a;
    15|      --bg-secondary: #1e293b;
    16|      --bg-card: #1a2332;
    17|      --border: #334155;
    18|      --text-primary: #e2e8f0;
    19|      --text-secondary: #94a3b8;
    20|      --accent: #00ffcc;
    21|      --accent-dim: rgba(0,255,204,0.12);
    22|      --accent2: #667eea;
    23|      --success: #22c55e;
    24|      --warning: #f59e0b;
    25|      --danger: #ef4444;
    26|      --orange: #f97316;
    27|      --info: #06b6d4;
    28|      --purple: #8b5cf6;
    29|      --sidebar-w: 220px;
    30|      --shadow: 0 4px 24px rgba(0,0,0,0.3);
    31|    }
    32|    html { scroll-behavior: smooth; }
    33|    body {
    34|      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    35|      background: var(--bg-primary);
    36|      color: var(--text-primary);
    37|      line-height: 1.6;
    38|      display: flex;
    39|      min-height: 100vh;
    40|    }
    41|    a { color: var(--accent); text-decoration: none; }
    42|    a:hover { opacity: 0.85; }
    43|
    44|    /* === SIDEBAR === */
    45|    .sidebar {
    46|      position: fixed;
    47|      top: 0; left: 0;
    48|      width: var(--sidebar-w);
    49|      height: 100vh;
    50|      background: #0a0f1a;
    51|      border-right: 1px solid var(--border);
    52|      display: flex;
    53|      flex-direction: column;
    54|      z-index: 100;
    55|      overflow-y: auto;
    56|    }
    57|    .sidebar-logo {
    58|      padding: 24px 20px 20px;
    59|      border-bottom: 1px solid var(--border);
    60|    }
    61|    .sidebar-logo h1 {
    62|      font-size: 16px;
    63|      font-weight: 800;
    64|      letter-spacing: 0.5px;
    65|      color: var(--accent);
    66|    }
    67|    .sidebar-logo span {
    68|      font-size: 10px;
    69|      color: var(--text-secondary);
    70|      letter-spacing: 2px;
    71|      text-transform: uppercase;
    72|    }
    73|    .sidebar-nav { flex: 1; padding: 16px 0; }
    74|    .sidebar-nav a {
    75|      display: flex;
    76|      align-items: center;
    77|      gap: 12px;
    78|      padding: 10px 20px;
    79|      color: var(--text-secondary);
    80|      font-size: 13px;
    81|      font-weight: 500;
    82|      transition: all 0.2s;
    83|      border-left: 3px solid transparent;
    84|    }
    85|    .sidebar-nav a:hover, .sidebar-nav a.active {
    86|      color: var(--text-primary);
    87|      background: rgba(0,255,204,0.05);
    88|      border-left-color: var(--accent);
    89|    }
    90|    .sidebar-nav a .icon { font-size: 16px; width: 20px; text-align: center; }
    91|    .sidebar-footer {
    92|      padding: 16px 20px;
    93|      border-top: 1px solid var(--border);
    94|      font-size: 11px;
    95|    }
    96|    .sidebar-footer a { color: var(--text-secondary); font-size: 11px; display: block; padding: 4px 0; }
    97|    .sidebar-footer a:hover { color: var(--accent); }
    98|
    99|    /* === MAIN CONTENT === */
   100|    .main {
   101|      margin-left: var(--sidebar-w);
   102|      flex: 1;
   103|      min-height: 100vh;
   104|    }
   105|    .container { max-width: 1400px; margin: 0 auto; padding: 28px 32px 40px; }
   106|
   107|    /* === HEADER / STATS === */
   108|    .hero {
   109|      margin-bottom: 32px;
   110|      animation: fadeIn 0.6s ease;
   111|    }
   112|    .hero h1 {
   113|      font-size: 28px;
   114|      font-weight: 800;
   115|      background: linear-gradient(135deg, var(--text-primary), var(--accent));
   116|      -webkit-background-clip: text;
   117|      -webkit-text-fill-color: transparent;
   118|      background-clip: text;
   119|    }
   120|    .hero p {
   121|      color: var(--text-secondary);
   122|      font-size: 14px;
   123|      margin-top: 2px;
   124|      letter-spacing: 0.3px;
   125|    }
   126|    .stat-row {
   127|      display: grid;
   128|      grid-template-columns: repeat(3, 1fr);
   129|      gap: 16px;
   130|      margin-top: 20px;
   131|    }
   132|    .stat-card {
   133|      background: var(--bg-card);
   134|      border: 1px solid var(--border);
   135|      border-radius: 12px;
   136|      padding: 20px 24px;
   137|      display: flex;
   138|      align-items: center;
   139|      gap: 16px;
   140|      transition: transform 0.2s, box-shadow 0.2s;
   141|    }
   142|    .stat-card:hover {
   143|      transform: translateY(-2px);
   144|      box-shadow: var(--shadow);
   145|    }
   146|    .stat-card .stat-icon {
   147|      width: 48px; height: 48px;
   148|      border-radius: 12px;
   149|      background: var(--accent-dim);
   150|      display: flex; align-items: center; justify-content: center;
   151|      font-size: 22px;
   152|      flex-shrink: 0;
   153|    }
   154|    .stat-card .stat-number {
   155|      font-size: 28px;
   156|      font-weight: 700;
   157|      color: var(--accent);
   158|      animation: pulseStat 2s ease-in-out infinite;
   159|    }
   160|    .stat-card .stat-label {
   161|      font-size: 12px;
   162|      color: var(--text-secondary);
   163|      margin-top: 2px;
   164|    }
   165|
   166|    /* === BLOCKER ALERTS === */
   167|    .blocker-alerts {
   168|      background: rgba(239,68,68,0.08);
   169|      border: 1px solid rgba(239,68,68,0.3);
   170|      border-radius: 10px;
   171|      padding: 16px 20px;
   172|      margin-bottom: 24px;
   173|      display: none;
