   175|    .blocker-alerts.show { display: block; }
   176|    .blocker-alerts h3 {
   177|      font-size: 14px;
   178|      font-weight: 700;
   179|      color: var(--danger);
   180|      margin-bottom: 10px;
   181|      display: flex;
   182|      align-items: center;
   183|      gap: 8px;
   184|    }
   185|    .blocker-alerts .alert-item {
   186|      display: flex;
   187|      align-items: center;
   188|      justify-content: space-between;
   189|      padding: 8px 12px;
   190|      background: rgba(239,68,68,0.05);
   191|      border-radius: 6px;
   192|      margin-bottom: 6px;
   193|      font-size: 13px;
   194|    }
   195|    .blocker-alerts .alert-item .alert-pipeline {
   196|      font-weight: 600;
   197|      color: var(--accent);
   198|    }
   199|    .blocker-alerts .alert-item .alert-lead { color: var(--text-primary); }
   200|    .blocker-alerts .alert-item .alert-days {
   201|      color: var(--danger);
   202|      font-weight: 700;
   203|    }
   204|
   205|    /* === SECTION TITLES === */
   206|    .section-title {
   207|      font-size: 20px;
   208|      font-weight: 700;
   209|      margin-bottom: 20px;
   210|      padding-bottom: 8px;
   211|      border-bottom: 1px solid var(--border);
   212|      display: flex;
   213|      align-items: center;
   214|      gap: 12px;
   215|      flex-wrap: wrap;
   216|    }
   217|    .section-title .email-badge {
   218|      font-size: 11px;
   219|      font-weight: 500;
   220|      background: var(--accent-dim);
   221|      color: var(--accent);
   222|      padding: 3px 10px;
   223|      border-radius: 20px;
   224|      font-family: monospace;
   225|      letter-spacing: -0.2px;
   226|    }
   227|    .section { margin-bottom: 48px; animation: fadeIn 0.5s ease; }
   228|
   229|    /* === OVERVIEW CARDS === */
   230|    .pipeline-cards {
   231|      display: grid;
   232|      grid-template-columns: repeat(3, 1fr);
   233|      gap: 16px;
   234|    }
   235|    .pipeline-overview-card {
   236|      background: var(--bg-card);
   237|      border: 1px solid var(--border);
   238|      border-radius: 12px;
   239|      padding: 24px;
   240|      cursor: pointer;
   241|      transition: transform 0.25s, box-shadow 0.25s;
   242|    }
   243|    .pipeline-overview-card:hover {
   244|      transform: translateY(-4px);
   245|      box-shadow: 0 8px 32px rgba(0,255,204,0.1);
   246|    }
   247|    .pipeline-overview-card h3 {
   248|      font-size: 16px;
   249|      font-weight: 700;
   250|      color: var(--accent);
   251|      margin-bottom: 4px;
   252|    }
   253|    .pipeline-overview-card .pipeline-email {
   254|      font-size: 11px;
   255|      color: var(--text-secondary);
   256|      font-family: monospace;
   257|      margin-bottom: 16px;
   258|    }
   259|    .pipeline-overview-card .stat-line {
   260|      display: flex;
   261|      justify-content: space-between;
   262|      font-size: 13px;
   263|      margin-bottom: 8px;
   264|    }
   265|    .pipeline-overview-card .stat-line strong { color: var(--text-primary); }
   266|    .pipeline-overview-card .stat-line span { color: var(--accent); font-weight: 600; }
   267|    .stage-bar {
   268|      display: flex;
   269|      height: 8px;
   270|      border-radius: 4px;
   271|      overflow: hidden;
   272|      margin: 8px 0 12px;
   273|    }
   274|    .stage-bar .seg { height: 100%; transition: width 0.6s ease; }
   275|    .pipeline-overview-card .products {
   276|      display: flex;
   277|      flex-wrap: wrap;
   278|      gap: 6px;
   279|      margin-top: 8px;
   280|    }
   281|    .pipeline-overview-card .products .tag {
   282|      font-size: 10px;
   283|      padding: 2px 8px;
   284|      border-radius: 4px;
   285|      background: var(--bg-secondary);
   286|      color: var(--text-secondary);
   287|      border: 1px solid var(--border);
   288|    }
   289|
   290|    /* === TABLES === */
   291|    .table-wrap {
   292|      overflow-x: auto;
   293|      border-radius: 10px;
   294|      border: 1px solid var(--border);
   295|    }
   296|    table {
   297|      width: 100%;
   298|      border-collapse: collapse;
   299|      font-size: 13px;
   300|    }
   301|    thead { background: #0a0f1a; }
   302|    th {
   303|      padding: 12px 14px;
   304|      text-align: left;
   305|      font-weight: 600;
   306|      color: var(--text-secondary);
   307|      font-size: 11px;
   308|      text-transform: uppercase;
   309|      letter-spacing: 0.5px;
   310|      border-bottom: 1px solid var(--border);
   311|    }
   312|    td {
   313|      padding: 10px 14px;
   314|      border-bottom: 1px solid var(--border);
   315|    }
   316|    tbody tr { background: var(--bg-card); transition: background 0.15s; }
   317|    tbody tr:nth-child(even) { background: #1a2635; }
   318|    tbody tr:hover { background: #1e2d42; }
   319|
   320|    /* === BADGES === */
   321|    .badge {
   322|      display: inline-block;
   323|      padding: 2px 10px;
   324|      border-radius: 12px;
   325|      font-size: 11px;
   326|      font-weight: 600;
   327|    }
   328|    .badge-stage-1 { background: #64748b33; color: #64748b; }
   329|    .badge-stage-2 { background: #3b82f633; color: #3b82f6; }
   330|    .badge-stage-3 { background: #8b5cf633; color: #8b5cf6; }
   331|    .badge-stage-4 { background: #06b6d433; color: #06b6d4; }
   332|    .badge-stage-5 { background: #f59e0b33; color: #f59e0b; }
   333|    .badge-stage-6 { background: #f9731633; color: #f97316; }
   334|    .badge-stage-7 { background: #22c55e33; color: #22c55e; }
   335|    .badge-stage-8 { background: #14b8a633; color: #14b8a6; }
   336|    .badge-icp-high   { background: #22c55e22; color: #22c55e; }
   337|    .badge-icp-mid    { background: #f59e0b22; color: #f59e0b; }
   338|    .badge-icp-low    { background: #f9731622; color: #f97316; }
   339|    .badge-stale      { background: #ef444422; color: #ef4444; }
   340|    .badge-status-new { background: #3b82f622; color: #3b82f6; }
   341|    .badge-status-active { background: #22c55e22; color: #22c55e; }
   342|
   343|    /* === PRODUCT / SERVICE TIER CARDS === */
   344|    .tier-grid {
   345|      display: grid;
   346|      grid-template-columns: repeat(3, 1fr);
   347|      gap: 14px;
   348|      margin-top: 16px;
   349|    }
   350|    .tier-card {
   351|      background: var(--bg-card);
   352|      border: 1px solid var(--border);
   353|      border-radius: 10px;
   354|      padding: 18px;
   355|      transition: transform 0.2s, box-shadow 0.2s;
   356|    }
   357|    .tier-card:hover {
   358|      transform: translateY(-2px);
   359|      box-shadow: var(--shadow);
   360|    }
   361|    .tier-card h4 { font-size: 14px; font-weight: 600; margin-bottom: 4px; }
   362|    .tier-card .price {
   363|      font-size: 20px;
   364|      font-weight: 700;
   365|      color: var(--accent);
   366|      margin-bottom: 6px;
   367|    }
   368|    .tier-card p { font-size: 12px; color: var(--text-secondary); }
   369|
   370|    /* === ACTION BUTTONS === */
   371|    .action-links {
   372|      display: flex;
   373|      gap: 10px;
   374|      margin-top: 16px;
   375|      flex-wrap: wrap;
   376|    }
   377|    .btn {
   378|      display: inline-flex;
   379|      align-items: center;
   380|      gap: 6px;
   381|      padding: 8px 18px;
   382|      border-radius: 8px;
   383|      font-size: 12px;
   384|      font-weight: 600;
   385|      border: none;
   386|      cursor: pointer;
   387|      transition: all 0.2s;
   388|      text-decoration: none;
   389|    }
   390|    .btn-primary {
   391|      background: var(--accent);
   392|      color: #0f172a;
   393|    }
   394|    .btn-primary:hover { background: #00e6b8; }
   395|    .btn-outline {
   396|      background: transparent;
   397|      color: var(--text-primary);
   398|      border: 1px solid var(--border);
   399|    }
   400|    .btn-outline:hover { border-color: var(--accent); color: var(--accent); }
   401|
   402|    /* === INTAKE / SEQUENCE GRID === */
   403|    .card-grid {
   404|      display: grid;
   405|      grid-template-columns: repeat(3, 1fr);
   406|      gap: 16px;
   407|    }
   408|    .index-card {
   409|      background: var(--bg-card);
   410|      border: 1px solid var(--border);
   411|      border-radius: 12px;
   412|      overflow: hidden;
   413|      transition: transform 0.25s, box-shadow 0.25s;
   414|    }
   415|    .index-card:hover {
   416|      transform: translateY(-3px);
   417|      box-shadow: 0 8px 32px rgba(0,0,0,0.4);
   418|    }
   419|    .index-card .gradient-block {
   420|      height: 80px;
   421|      display: flex;
   422|      align-items: center;
   423|      justify-content: center;
   424|      font-size: 32px;
   425|    }
   426|    .index-card .card-body {
   427|      padding: 18px;
   428|    }
   429|    .index-card .card-body h4 { font-size: 15px; font-weight: 600; margin-bottom: 4px; }
   430|    .index-card .card-body .desc { font-size: 12px; color: var(--text-secondary); margin-bottom: 8px; }
   431|    .index-card .card-body .meta { font-size: 11px; color: var(--text-secondary); font-family: monospace; }
   432|    .index-card .card-body .btn { margin-top: 10px; }
   433|
   434|    /* === BOOK LIST === */
   435|    .book-list {
   436|      display: grid;
   437|      grid-template-columns: 1fr 1fr;
   438|      gap: 8px;
   439|      margin: 12px 0;
   440|    }
   441|    .book-item {
   442|      background: var(--bg-secondary);
   443|      border: 1px solid var(--border);
   444|      border-radius: 8px;
   445|      padding: 10px 14px;
   446|      font-size: 12px;
   447|    }
   448|    .book-item .b-title { font-weight: 600; }
   449|    .book-item .b-price { color: var(--accent); font-weight: 600; }
   450|
   451|    /* === BULK TIERS === */
   452|    .bulk-tiers {
   453|      display: flex;
   454|      gap: 10px;
   455|      flex-wrap: wrap;
