   467|    .bulk-tier .bt-range { color: var(--text-secondary); font-size: 11px; }
   468|
   469|    /* === FOOTER === */
   470|    .footer {
   471|      margin-top: 48px;
   472|      padding: 24px 0;
   473|      border-top: 1px solid var(--border);
   474|      text-align: center;
